<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api } from '@smart-merchant/api'
import { ElMessage } from 'element-plus'
import { type Order, type Store, money, dateText, orderStatus, statusLabels, exportCsv } from '../model'
const props=defineProps<{orders:Order[];stores:Store[];storeId:number;financeAllowed:boolean;refundAllowed?:boolean;shipAllowed?:boolean;revision:number;view?:string}>()
const keyword=ref(''),status=ref(''),dates=ref<[string,string]|null>(null),current=ref(1),size=ref(10),tab=ref(props.view??'orders'),detail=ref<Order|null>(null)
type Entry={id:number;storeId:number;businessType:string;businessId:number;direction:string;amountCents:number;occurredAt:string;remark:string}
const ledger=ref<Entry[]>([]),busy=ref(false),error=ref('')
const refundRequest=ref<{status:string;reason:string;reply:string}|null>(null),refundReply=ref(''),refundBusy=ref(false)
watch(detail,async value=>{refundRequest.value=null;refundReply.value='';if(!value)return;try{const rows=await api<{status:string;reason:string;reply:string}[]>(`/api/merchant/v1/orders/${value.id}/refund-request`);if(detail.value?.id===value.id)refundRequest.value=rows[0]??null}catch(e){ElMessage.error((e as Error).message)}})
async function decideRefund(approve:boolean){if(!detail.value||!refundReply.value.trim()||refundBusy.value)return;refundBusy.value=true;try{const id=detail.value.id;await api(`/api/merchant/v1/orders/${id}/refund-request`,{method:'POST',body:JSON.stringify({approve,reply:refundReply.value.trim()})});detail.value=await api<Order>(`/api/merchant/v1/orders/${id}`);ElMessage.success('申请已处理，请刷新订单列表')}catch(e){ElMessage.error((e as Error).message)}finally{refundBusy.value=false}}
const emit=defineEmits<{changed:[order:Order]}>()
const carrier=ref(''),trackingNo=ref(''),shipping=ref(false)
watch(()=>detail.value?.id,()=>{carrier.value='';trackingNo.value=''})
async function ship(){if(!detail.value||shipping.value)return;shipping.value=true;try{detail.value=await api<Order>(`/api/merchant/v1/orders/${detail.value.id}/ship`,{method:'POST',body:JSON.stringify({carrier:carrier.value.trim(),trackingNo:trackingNo.value.trim()})});ElMessage.success('发货信息已保存');emit('changed',detail.value)}catch(e){ElMessage.error((e as Error).message)}finally{shipping.value=false}}
const scope=computed(()=>props.orders.filter(x=>!props.storeId||x.storeId===props.storeId))
const filtered=computed(()=>scope.value.filter(o=>(!status.value||o.status===status.value)&&(!keyword.value.trim()||[o.orderNo,o.customerName,o.customerMobile,...(o.items??[]).map(i=>i.productName)].some(x=>x?.toLowerCase().includes(keyword.value.trim().toLowerCase())))&&(!dates.value||(o.paidAt&&o.paidAt.slice(0,10)>=dates.value[0]&&o.paidAt.slice(0,10)<=dates.value[1]))))
const pageRows=computed(()=>filtered.value.slice((current.value-1)*size.value,current.value*size.value))
const paid=computed(()=>filtered.value.filter(o=>o.paidAt)), completed=computed(()=>filtered.value.filter(o=>o.status==='COMPLETED'))
const paidAmount=computed(()=>paid.value.reduce((n,o)=>n+o.payableAmountCents,0))
const completedAmount=computed(()=>completed.value.reduce((n,o)=>n+o.totalAmountCents,0))
watch([keyword,status,dates,()=>props.storeId,size],()=>current.value=1,{deep:true})
const storeName=(id:number)=>props.stores.find(s=>s.id===id)?.storeName??String(id)
function reset(){keyword.value='';status.value='';dates.value=null}
function download(){exportCsv('订单明细.csv',[['订单号','门店','顾客','手机号','状态','商品总额（元）','优惠券（元）','积分抵扣（元）','储值支付（元）','现金应付（元）','支付时间','核销时间'],...filtered.value.map(o=>[o.orderNo,storeName(o.storeId),o.customerName,o.customerMobile,orderStatus(o.status),(o.totalAmountCents/100).toFixed(2),(o.couponDiscountCents/100).toFixed(2),(o.pointsUsed/100).toFixed(2),(o.storedValueUsedCents/100).toFixed(2),(o.payableAmountCents/100).toFixed(2),dateText(o.paidAt),dateText(o.verifiedAt)])])}
let serial=0
async function loadLedger(){if(tab.value!=='finance'||!props.financeAllowed)return;const id=++serial;busy.value=true;error.value='';ledger.value=[];try{const result=await Promise.all(props.stores.filter(s=>!props.storeId||s.id===props.storeId).map(async s=>(await api<Omit<Entry,'storeId'>[]>(`/api/merchant/v1/settlements/finance-ledger?storeId=${s.id}`)).map(x=>({...x,storeId:s.id}))));if(id===serial)ledger.value=result.flat().sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt))}catch(e){if(id===serial)error.value=(e as Error).message}finally{if(id===serial)busy.value=false}}
watch(()=>props.view,v=>{tab.value=v??'orders'})
watch([tab,()=>props.storeId,()=>props.revision],loadLedger,{immediate:true})
const filteredLedger=computed(()=>ledger.value.filter(x=>!dates.value||(x.occurredAt.slice(0,10)>=dates.value[0]&&x.occurredAt.slice(0,10)<=dates.value[1])))
const income=computed(()=>filteredLedger.value.filter(x=>x.direction==='INCOME').reduce((n,x)=>n+x.amountCents,0)),outgoing=computed(()=>filteredLedger.value.filter(x=>x.direction==='EXPENSE').reduce((n,x)=>n+x.amountCents,0))
function exportLedger(){exportCsv('财务流水.csv',[['流水号','门店','业务','业务单号','方向','金额（元）','发生时间','备注'],...filteredLedger.value.map(x=>[x.id,storeName(x.storeId),x.businessType,x.businessId,x.direction==='INCOME'?'收入':'支出',(x.amountCents/100).toFixed(2),dateText(x.occurredAt),x.remark??''])])}
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">ORDERS & REVENUE</div><h1>{{tab==='orders'?'销售订单':'财务流水'}}</h1><p>查询本门店交易明细、金额抵扣及核销收支。</p></div><el-button :disabled="tab==='orders'?!filtered.length:!filteredLedger.length" @click="tab==='orders'?download():exportLedger()">导出{{tab==='orders'?'订单':'流水'}}</el-button></div>

  <template v-if="tab==='orders'">
    <section class="metric-grid"><article class="metric"><div>筛选订单总数</div><strong>{{filtered.length}} <small>笔</small></strong><p>当前条件下的全部订单</p></article><article class="metric primary"><div>支付金额</div><strong>{{money(paidAmount)}}</strong><p>{{paid.length}} 笔已支付 · 含后续退款订单</p></article><article class="metric"><div>核销商品总额</div><strong>{{money(completedAmount)}}</strong><p>{{completed.length}} 笔已完成订单的商品原价</p></article><article class="metric"><div>待到店自提</div><strong>{{filtered.filter(x=>x.status==='PICKUP_READY'&&!x.directTransferId).length}} <small>笔</small></strong><p>已付款，等待门店核销</p></article></section>
    <div class="panel"><div class="filter-bar compact"><el-input v-model="keyword" placeholder="搜索订单号、顾客、手机号、商品" clearable/><el-select v-model="status" placeholder="全部订单状态" clearable><el-option v-for="(label,key) in statusLabels" :key="key" :label="label" :value="key"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="支付开始日期" end-placeholder="支付结束日期"/><el-button @click="reset">重置</el-button></div><p class="subtle">设置日期后按支付时间筛选，待支付订单不纳入期间统计。</p>
      <el-table :data="pageRows" empty-text="暂无符合筛选条件的订单" stripe><el-table-column label="订单 / 门店" min-width="205"><template #default="s"><div class="cell-stack"><b>{{s.row.orderNo}}</b><small>{{storeName(s.row.storeId)}}</small></div></template></el-table-column><el-table-column label="顾客" min-width="150"><template #default="s"><div class="cell-stack"><span>{{s.row.customerName}}</span><small>{{s.row.customerMobile}}</small></div></template></el-table-column><el-table-column label="商品" min-width="180"><template #default="s"><div class="cell-stack"><span class="ellipsis">{{s.row.items?.[0]?.productName??'—'}}</span><small>共 {{s.row.totalQuantity}} 件商品</small></div></template></el-table-column><el-table-column label="现金应付" width="125" sortable :sort-method="(a:Order,b:Order)=>a.payableAmountCents-b.payableAmountCents"><template #default="s"><b>{{money(s.row.payableAmountCents)}}</b></template></el-table-column><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="s.row.status==='COMPLETED'?'success':s.row.status==='REFUNDED'?'danger':s.row.status==='CLOSED'?'info':'warning'" effect="light">{{s.row.status==='PICKUP_READY'&&s.row.directTransferId?'直寄待出库':orderStatus(s.row.status)}}</el-tag></template></el-table-column><el-table-column label="支付时间" min-width="175"><template #default="s">{{dateText(s.row.paidAt)}}</template></el-table-column><el-table-column label="操作" fixed="right" width="85"><template #default="s"><el-button link type="primary" @click="detail=s.row">详情</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{filtered.length}} 笔订单</span><el-pagination v-model:current-page="current" v-model:page-size="size" :page-sizes="[10,20,50]" :total="filtered.length" layout="sizes, prev, pager, next"/></div>
    </div>
  </template>
  <template v-else><section class="metric-grid three"><article class="metric"><div>核销入账（商品原价）</div><strong>{{error?'—':money(income)}}</strong></article><article class="metric"><div>退款出账（商品原价）</div><strong>{{error?'—':money(outgoing)}}</strong></article><article class="metric primary"><div>核销收支净额</div><strong>{{error?'—':money(income-outgoing)}}</strong></article></section><div class="panel" v-loading="busy"><div class="filter-bar compact"><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="发生开始日期" end-placeholder="发生结束日期"/><el-button @click="loadLedger">刷新流水</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><p class="subtle">现有财务流水按核销商品原价入账、退款出账；现金实收请查看订单支付明细和经营总览。</p><el-table :data="filteredLedger" empty-text="当前范围暂无财务流水"><el-table-column label="门店" min-width="130"><template #default="s">{{storeName(s.row.storeId)}}</template></el-table-column><el-table-column prop="businessType" label="业务类型"/><el-table-column prop="businessId" label="业务单号" min-width="170"/><el-table-column label="收支方向"><template #default="s"><el-tag :type="s.row.direction==='INCOME'?'success':'danger'">{{s.row.direction==='INCOME'?'收入':'支出'}}</el-tag></template></el-table-column><el-table-column label="金额"><template #default="s">{{money(s.row.amountCents)}}</template></el-table-column><el-table-column label="发生时间" min-width="175"><template #default="s">{{dateText(s.row.occurredAt)}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="180"/></el-table></div></template>
  <el-drawer :model-value="Boolean(detail)" @close="detail=null" title="订单详情" size="min(720px, 100vw)"><template v-if="detail"><div class="detail-banner"><span>{{orderStatus(detail.status)}}</span><h2>{{detail.orderNo}}</h2><p>{{storeName(detail.storeId)}} · {{detail.customerName}} · {{detail.customerMobile}}</p></div><section v-if="refundRequest" class="panel"><h3>消费者退款申请</h3><p>{{refundRequest.reason}}</p><p>状态：{{refundRequest.status==='PENDING'?'待处理':refundRequest.status==='APPROVED'?'已同意':'已拒绝'}}</p><p v-if="refundRequest.reply">回复：{{refundRequest.reply}}</p><template v-if="refundRequest.status==='PENDING'&&refundAllowed"><el-input v-model="refundReply" type="textarea" maxlength="500" placeholder="填写处理说明"/><div style="margin-top:12px"><el-button :disabled="!refundReply.trim()||refundBusy" @click="decideRefund(false)">拒绝申请</el-button><el-button type="primary" :disabled="!refundReply.trim()||refundBusy" @click="decideRefund(true)">同意并执行退款</el-button></div></template></section><section v-if="detail.delivery?.method==='SHIPPING'" class="panel"><h3>快递邮寄</h3><p>{{detail.delivery.name}} · {{detail.delivery.phone}}</p><p>{{detail.delivery.address}}</p><p v-if="detail.delivery.trackingNo">{{detail.delivery.carrier}} · {{detail.delivery.trackingNo}}</p><p v-if="detail.delivery.shippedAt">发货时间：{{dateText(detail.delivery.shippedAt)}}</p><el-form v-if="detail.status==='PENDING_SHIPMENT'&&shipAllowed" label-position="top" @submit.prevent="ship"><el-form-item label="快递公司"><el-input v-model="carrier" maxlength="64"/></el-form-item><el-form-item label="快递单号"><el-input v-model="trackingNo" maxlength="96"/></el-form-item><el-button type="primary" native-type="submit" :disabled="shipping||!carrier.trim()||!trackingNo.trim()">确认发货</el-button></el-form></section><h3>商品清单</h3><el-table :data="detail.items"><el-table-column prop="productName" label="商品" min-width="160"/><el-table-column prop="skuName" label="规格"/><el-table-column label="单价"><template #default="s">{{money(s.row.unitPriceCents)}}</template></el-table-column><el-table-column prop="quantity" label="数量" width="65"/><el-table-column label="小计"><template #default="s">{{money(s.row.lineAmountCents)}}</template></el-table-column></el-table><h3>金额明细</h3><dl class="amount-list"><div v-if="detail.delivery?.method==='SHIPPING'"><dt>消费者支付运费</dt><dd>{{money(detail.delivery.shippingFeeCents)}}</dd></div><div><dt>商品总额</dt><dd>{{money(detail.totalAmountCents)}}</dd></div><div><dt>优惠券抵扣</dt><dd>− {{money(detail.couponDiscountCents)}}</dd></div><div><dt>积分抵扣（{{detail.pointsUsed}} 积分）</dt><dd>− {{money(detail.pointsUsed)}}</dd></div><div><dt>储值支付</dt><dd>− {{money(detail.storedValueUsedCents)}}</dd></div><div class="total"><dt>现金应付金额</dt><dd>{{money(detail.payableAmountCents)}}</dd></div></dl><h3>订单进度</h3><el-timeline><el-timeline-item :timestamp="dateText(detail.paidAt)" :type="detail.paidAt?'primary':'info'">支付{{detail.paidAt?'成功':'待完成'}}</el-timeline-item><el-timeline-item v-if="detail.verifiedAt" :timestamp="dateText(detail.verifiedAt)" type="success">{{detail.delivery?.method==='SHIPPING'?'消费者确认收货':'到店核销完成'}}</el-timeline-item><el-timeline-item v-if="detail.closedAt" :timestamp="dateText(detail.closedAt)">订单关闭</el-timeline-item><el-timeline-item v-if="['REFUNDING','REFUNDED'].includes(detail.status)" type="warning">{{orderStatus(detail.status)}} · 退款金额及时间请查看财务流水</el-timeline-item></el-timeline><p class="subtle">核销成功后计入本店业绩；退款按授权业务流程处理。</p></template></el-drawer>
</template>
